$ErrorActionPreference = "Stop"# Check if virtual environment existsif (-not (Test-Path ".\venv")) {    Write-Host "Creating virtual environment..."    python -m venv venv}# Activate virtual environmentWrite-Host "Activating virtual environment..."# For PowerShell 5.1+ (Windows PowerShell)If ($PSVersionTable.PSVersion.Major -lt 6) {    .\venv\Scripts\Activate.ps1} Else { # For PowerShell 6+ (PowerShell Core)    . .\venv\Scripts\Activate.ps1}# Install dependenciesif (Test-Path "requirements.txt") {    Write-Host "Installing dependencies from requirements.txt..."    pip install --no-cache-dir -r requirements.txt}# Run the FastAPI applicationWrite-Host "Starting FastAPI application..."uvicorn app.main:app --host 0.0.0.0 --port 8000 --reload